            <span className="text-xs font-semibold tracking-wider">PT</span>
          </>
        ) : (
          <>
            <Globe className="w-3.5 h-3.5" />
            <span className="text-xs font-semibold tracking-wider">EN</span>
          </>
        )}
      </button>
    </div>
  );
}

