            <Button onClick={handleSave} disabled={isLoading || updateMutation.isPending} data-testid="button-save-management-settings">
              {updateMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Salvar alterações
            </Button>
          </div>
        </section>
      </div>
    </div>
  );
}

