                { en: "High Fidelity", pt: "Alta Fidelidade", icon: "🎙️" },
                { en: "Real-time", pt: "Tempo Real", icon: "⚡" },
                { en: "Smart Sync", pt: "Sincronia Inteligente", icon: "🧠" },
