export type SessionStatus = "scheduled" | "in_progress" | "completed";

export function computeSessionStatus(
  scheduledAt: string | Date,
  durationMinutes: number = 60
): SessionStatus {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  const end = start + durationMinutes * 60 * 1000;
  if (now < start) return "scheduled";
  if (now < end) return "in_progress";
  return "completed";
}

export function isSessionVisibleOnDashboard(
  scheduledAt: string | Date,
  durationMinutes: number = 60
): boolean {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  const windowEnd = start + 3 * 60 * 60 * 1000;
  return now < windowEnd;
}

export function sessionEntryAllowed(
  scheduledAt: string | Date,
  bufferMinutes: number = 5
): boolean {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  return now >= start - bufferMinutes * 60 * 1000;
}

export function formatCountdownTime(scheduledAt: string | Date, bufferMinutes: number = 5): string {
  const target = new Date(scheduledAt).getTime() - bufferMinutes * 60 * 1000;
  const diff = Math.max(0, target - Date.now());
  const hours = Math.floor(diff / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  if (hours > 0) return `${hours}h ${minutes}min`;
  return `${minutes}min`;
}

export interface ScrollAnchor {
  time: number;
  scrollTop: number;
}

export function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value));
}

export function buildScrollAnchors(params: {
  lineStarts: number[];
  lineOffsets: number[];
  lineHeights: number[];
  viewportHeight: number;
  maxScrollTop: number;
}) {
  const { lineStarts, lineOffsets, lineHeights, viewportHeight, maxScrollTop } = params;
  const anchors: ScrollAnchor[] = [];
  for (let i = 0; i < lineStarts.length; i++) {
    const center = lineOffsets[i] + lineHeights[i] / 2 - viewportHeight / 2;
    anchors.push({
      time: Math.max(0, lineStarts[i] || 0),
      scrollTop: clamp(center, 0, Math.max(0, maxScrollTop)),
    });
  }
  return anchors.sort((a, b) => a.time - b.time);
}

export function interpolateScrollTop(anchors: ScrollAnchor[], videoTime: number) {
  if (!anchors.length) return 0;
  if (anchors.length === 1) return anchors[0].scrollTop;
  if (videoTime <= anchors[0].time) return anchors[0].scrollTop;
  const last = anchors[anchors.length - 1];
  if (videoTime >= last.time) return last.scrollTop;

  let low = 0;
  let high = anchors.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const t = anchors[mid].time;
    if (t === videoTime) return anchors[mid].scrollTop;
    if (t < videoTime) low = mid + 1;
    else high = mid - 1;
  }

  const rightIndex = clamp(low, 1, anchors.length - 1);
  const leftIndex = rightIndex - 1;
  const left = anchors[leftIndex];
  const right = anchors[rightIndex];
  const span = Math.max(0.0001, right.time - left.time);
  const ratio = clamp((videoTime - left.time) / span, 0, 1);
  return left.scrollTop + (right.scrollTop - left.scrollTop) * ratio;
}

export function computeAdaptiveMaxSpeedPxPerSec(params: {
  contentHeight: number;
  viewportHeight: number;
  videoDuration: number;
  lineCount: number;
  seeking: boolean;
}) {
  const { contentHeight, viewportHeight, videoDuration, lineCount, seeking } = params;
  const totalScrollable = Math.max(0, contentHeight - viewportHeight);
  const duration = Math.max(1, videoDuration);
  const density = totalScrollable / duration;
  const lineFactor = 1 + Math.min(0.6, lineCount / 800);
  const base = clamp(density * 1.65 * lineFactor + 120, 140, 2200);
  if (seeking) return Math.max(base, 3200);
  return base;
}

export function smoothScrollStep(params: {
  current: number;
  target: number;
  dtSeconds: number;
  maxSpeedPxPerSec: number;
  response: number;
}) {
  const { current, target, dtSeconds, maxSpeedPxPerSec, response } = params;
  const safeDt = Math.max(1 / 240, Math.min(0.12, dtSeconds));
  const alpha = 1 - Math.exp(-Math.max(0.1, response) * safeDt);
  const desired = (target - current) * alpha;
  const maxStep = maxSpeedPxPerSec * safeDt;
  const step = clamp(desired, -maxStep, maxStep);
  const next = current + step;
  return Math.abs(target - next) < 0.1 ? target : next;
}

import { QueryClient, QueryFunction } from "@tanstack/react-query";

async function throwIfResNotOk(res: Response) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    throw new Error(`${res.status}: ${text}`);
  }
}

export async function apiRequest(
  method: string,
  url: string,
  data?: unknown | undefined,
): Promise<Response> {
  const res = await fetch(url, {
    method,
    headers: data ? { "Content-Type": "application/json" } : {},
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  await throwIfResNotOk(res);
  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const res = await fetch(queryKey.join("/") as string, {
      credentials: "include",
    });

    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
      return null;
    }

    if (res.status === 401) {
      const { memoryNavigate } = await import("@studio/lib/memory-router");
      memoryNavigate("/login");
      return null;
    }

    await throwIfResNotOk(res);
    return await res.json();
  };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: getQueryFn({ on401: "throw" }),
      refetchInterval: false,
      refetchOnWindowFocus: false,
      staleTime: Infinity,
      retry: false,
    },
    mutations: {
      retry: false,
    },
  },
});

export type VideoLoopWindow = {
  startTime: number;
  endTime: number;
  duration: number;
};

export function computeMidVideoLoopWindow(
  mediaDurationSeconds: number,
  clipDurationSeconds = 8,
): VideoLoopWindow {
  const safeDuration = Number.isFinite(mediaDurationSeconds) ? Math.max(0, mediaDurationSeconds) : 0;
  const requestedClip = Math.max(5, Math.min(10, clipDurationSeconds));
  if (safeDuration <= 0) {
    return { startTime: 0, endTime: requestedClip, duration: requestedClip };
  }

  const effectiveClip = Math.min(requestedClip, safeDuration);
  const middle = safeDuration / 2;
  const startTime = Math.max(0, middle - effectiveClip / 2);
  const endTime = Math.min(safeDuration, startTime + effectiveClip);
  return { startTime, endTime, duration: Math.max(0.1, endTime - startTime) };
}

export function isPlayableVideoUrl(url: unknown) {
  const value = String(url || "").trim();
  if (!value) return false;
  return /^https?:\/\//i.test(value) || value.startsWith("/") || value.startsWith("blob:");
}

import { useSyncExternalStore } from "react";

const readPath = () => `${window.location.pathname}${window.location.search}` || "/";

const listeners = new Set<() => void>();

const notify = () => {
  listeners.forEach((listener) => listener());
};

const normalizeTarget = (to: string) => {
  if (!to) return "/hub-dub";
  return to.startsWith("/hub-dub") ? to : `/hub-dub${to.startsWith("/") ? "" : "/"}${to}`;
};

const onPopState = () => notify();
window.addEventListener("popstate", onPopState);

const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
};

export const memoryNavigate = (to: string, opts?: any) => {
  const target = normalizeTarget(to);
  const replace = Boolean(opts?.replace);
  const current = readPath();
  if (current !== target) {
    if (replace) {
      window.history.replaceState({}, "", target);
    } else {
      window.history.pushState({}, "", target);
    }
  }
  notify();
};

export const memoryHook = (): [string, typeof memoryNavigate] => {
  const fullPath = useSyncExternalStore(subscribe, readPath, readPath);
  return [fullPath.split("?")[0] || "/", memoryNavigate];
};

export const memorySearchHook = (): string => {
  const fullPath = useSyncExternalStore(subscribe, readPath, readPath);
  const idx = fullPath.indexOf("?");
  return idx === -1 ? "" : fullPath.slice(idx + 1);
};

export function isUnauthorizedError(error: Error): boolean {
  return /^401: .*Unauthorized/.test(error.message);
}

// Redirect to login with a toast notification
export function redirectToLogin(toast?: (options: { title: string; description: string; variant: string }) => void) {
  if (toast) {
    toast({
      title: "Unauthorized",
      description: "You are logged out. Logging in again...",
      variant: "destructive",
    });
  }
  setTimeout(async () => {
    const { memoryNavigate } = await import("@studio/lib/memory-router");
    memoryNavigate("/login");
  }, 500);
}

export async function authFetch(url: string, options: RequestInit = {}) {
  const headers = new Headers(options.headers);

  if (!headers.has("Content-Type") && options.body && typeof options.body === "string") {
    headers.set("Content-Type", "application/json");
  }

  const res = await fetch(url, { ...options, headers, credentials: "include" });

  if (res.status === 401) {
    const { memoryNavigate } = await import("@studio/lib/memory-router");
    memoryNavigate("/login");
    throw new Error("Unauthorized");
  }

  if (!res.ok) {
    let errorMsg = res.statusText;
    try {
      const contentType = res.headers.get("content-type") || "";
      if (contentType.includes("application/json")) {
        const data = await res.json();
        if (data.message) errorMsg = data.message;
      } else {
        const text = await res.text();
        if (text) errorMsg = text.slice(0, 200);
      }
    } catch {}
    throw new Error(errorMsg);
  }

  if (res.status === 204) return null;
  const contentType = res.headers.get("content-type") || "";
  if (contentType.includes("application/json")) {
    return res.json();
  }
  const text = await res.text().catch(() => "");
  throw new Error(text ? `Resposta invalida do servidor: ${text.slice(0, 200)}` : "Resposta invalida do servidor");
}

import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@studio/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

