const SAMPLE_RATE = 48000;
const BIT_DEPTH = 24;
const NUM_CHANNELS = 1;

export function encodeWav(samples: Float32Array): ArrayBuffer {
  const bytesPerSample = BIT_DEPTH / 8;
  const dataLength = samples.length * bytesPerSample;
  const headerLength = 44;
  const totalLength = headerLength + dataLength;

  const buffer = new ArrayBuffer(totalLength);
  const view = new DataView(buffer);

  writeString(view, 0, "RIFF");
  view.setUint32(4, totalLength - 8, true);
  writeString(view, 8, "WAVE");

  writeString(view, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, NUM_CHANNELS, true);
  view.setUint32(24, SAMPLE_RATE, true);
  view.setUint32(28, SAMPLE_RATE * NUM_CHANNELS * bytesPerSample, true);
  view.setUint16(32, NUM_CHANNELS * bytesPerSample, true);
  view.setUint16(34, BIT_DEPTH, true);

  writeString(view, 36, "data");
  view.setUint32(40, dataLength, true);

  let offset = headerLength;
  for (let i = 0; i < samples.length; i++) {
    const clamped = Math.max(-1, Math.min(1, samples[i]));
    const intVal = clamped < 0
      ? Math.round(clamped * 0x800000)
      : Math.round(clamped * 0x7fffff);

    view.setUint8(offset, intVal & 0xff);
    view.setUint8(offset + 1, (intVal >> 8) & 0xff);
    view.setUint8(offset + 2, (intVal >> 16) & 0xff);
    offset += 3;
  }

  return buffer;
}

function writeString(view: DataView, offset: number, str: string): void {
  for (let i = 0; i < str.length; i++) {
    view.setUint8(offset + i, str.charCodeAt(i));
  }
}

export function wavToBlob(wavBuffer: ArrayBuffer): Blob {
  return new Blob([wavBuffer], { type: "audio/wav" });
}

export function getDurationSeconds(samples: Float32Array): number {
  return samples.length / SAMPLE_RATE;
}

export interface DrawOscilloscopeOpts {
  ctx: CanvasRenderingContext2D;
  timeDomainData: Uint8Array;
  width: number;
  height: number;
  color?: string;
}

export interface DrawStaticWaveformOpts {
  ctx: CanvasRenderingContext2D;
  samples: Float32Array;
  width: number;
  height: number;
  playheadPosition?: number;
  color?: string;
  playedColor?: string;
}

export interface DrawVuMeterOpts {
  ctx: CanvasRenderingContext2D;
  level: number;
  peak: number;
  width: number;
  height: number;
}

export function computeRMS(timeDomainData: Uint8Array): number {
  let sum = 0;
  for (let i = 0; i < timeDomainData.length; i++) {
    const v = (timeDomainData[i] - 128) / 128;
    sum += v * v;
  }
  return Math.sqrt(sum / timeDomainData.length);
}

export function rmsToMeterLevel(rms: number): number {
  if (rms <= 0.0001) return 0;
  const db = 20 * Math.log10(rms);
  const minDb = -60;
  const maxDb = 0;
  return Math.max(0, Math.min(1, (db - minDb) / (maxDb - minDb)));
}

export function drawOscilloscope({
  ctx,
  timeDomainData,
  width,
  height,
  color = "#22c55e",
}: DrawOscilloscopeOpts): void {
  ctx.clearRect(0, 0, width, height);

  ctx.strokeStyle = color;
  ctx.lineWidth = 1.5;
  ctx.shadowBlur = 6;
  ctx.shadowColor = color;
  ctx.lineJoin = "round";

  ctx.beginPath();
  const sliceWidth = width / timeDomainData.length;
  let x = 0;

  for (let i = 0; i < timeDomainData.length; i++) {
    const v = timeDomainData[i] / 128.0;
    const y = (v * height) / 2;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    x += sliceWidth;
  }
  ctx.lineTo(width, height / 2);
  ctx.stroke();

  ctx.shadowBlur = 0;
}

export function drawStaticWaveform({
  ctx,
  samples,
  width,
  height,
  playheadPosition = -1,
  color = "#22c55e",
  playedColor = "#3b82f6",
}: DrawStaticWaveformOpts): void {
  ctx.clearRect(0, 0, width, height);

  if (samples.length === 0) return;

  const mid = height / 2;
  const buckets = width;
  const samplesPerBucket = Math.max(1, Math.floor(samples.length / buckets));

  for (let b = 0; b < buckets; b++) {
    const start = b * samplesPerBucket;
    let max = 0;
    let min = 0;

    for (let j = 0; j < samplesPerBucket && start + j < samples.length; j++) {
      const s = samples[start + j];
      if (s > max) max = s;
      if (s < min) min = s;
    }

    const isPlayed = playheadPosition >= 0 && b / buckets <= playheadPosition;
    ctx.fillStyle = isPlayed ? playedColor : color;

    const top = mid - max * mid;
    const bottom = mid - min * mid;
    ctx.fillRect(b, top, 1, Math.max(1, bottom - top));
  }

  if (playheadPosition >= 0 && playheadPosition <= 1) {
    const x = Math.round(playheadPosition * width);
    ctx.fillStyle = "rgba(255,255,255,0.9)";
    ctx.fillRect(x, 0, 2, height);
  }
}

export function drawVuMeter({
  ctx,
  level,
  peak,
  width,
  height,
}: DrawVuMeterOpts): void {
  ctx.clearRect(0, 0, width, height);

  const greenEnd = 0.8;
  const yellowEnd = 0.9;

  const totalBars = 24;
  const barH = Math.floor((height - totalBars) / totalBars);
  const barGap = 1;

  for (let i = 0; i < totalBars; i++) {
    const barFraction = (i + 1) / totalBars;
    const y = height - i * (barH + barGap) - barH;

    const active = barFraction <= level;

    let baseColor: string;
    if (barFraction > yellowEnd) {
      baseColor = active ? "#ef4444" : "#3f1212";
    } else if (barFraction > greenEnd) {
      baseColor = active ? "#eab308" : "#2d2506";
    } else {
      baseColor = active ? "#22c55e" : "#0a2414";
    }

    ctx.fillStyle = baseColor;
    ctx.fillRect(0, y, width, barH);
  }

  const peakBar = Math.round(peak * totalBars);
  if (peakBar > 0 && peakBar <= totalBars) {
    const py =
      height - (peakBar - 1) * (barH + barGap) - barH;
    ctx.fillStyle =
      peak > yellowEnd
        ? "#ef4444"
        : peak > greenEnd
          ? "#eab308"
          : "#22c55e";
    ctx.fillRect(0, py, width, 2);
  }

  const dbLabels = [
    { label: "0", fraction: 1.0 },
    { label: "-6", fraction: 0.9 },
    { label: "-12", fraction: 0.8 },
  ];
  ctx.fillStyle = "#52525b";
  ctx.font = "8px monospace";
  ctx.textAlign = "center";

  for (const { label, fraction } of dbLabels) {
    const y =
      height -
      Math.round(fraction * totalBars) * (barH + barGap) +
      barH / 2;
    ctx.fillText(label, width / 2, y);
  }
}

import type { MicrophoneState } from "./microphoneManager";

const SAMPLE_RATE = 48000;
const BUFFER_SIZE = 4096;

export type RecordingStatus =
  | "idle"
  | "countdown"
  | "recording"
  | "recorded"
  | "previewing";

export interface RecordingResult {
  samples: Float32Array;
  durationSeconds: number;
}

let scriptProcessorNode: ScriptProcessorNode | null = null;
let recordedChunks: Float32Array[] = [];
let totalSamples = 0;

export function startCapture(micState: MicrophoneState): void {
  recordedChunks = [];
  totalSamples = 0;

  if (micState.audioContext.state === "suspended") {
    micState.audioContext.resume().then(() => {
      console.log("[RecEngine] AudioContext resumed before capture");
    });
  }

  scriptProcessorNode = micState.audioContext.createScriptProcessor(
    BUFFER_SIZE,
    1,
    1
  );

  scriptProcessorNode.onaudioprocess = (event) => {
    const input = event.inputBuffer.getChannelData(0);
    const copy = new Float32Array(input.length);
    copy.set(input);
    recordedChunks.push(copy);
    totalSamples += copy.length;
  };

  micState.gainNode.connect(scriptProcessorNode);
  scriptProcessorNode.connect(micState.audioContext.destination);
  console.log("[RecEngine] Capture started, sampleRate:", micState.audioContext.sampleRate);
}

export function stopCapture(micState: MicrophoneState): RecordingResult {
  console.log("[RecEngine] Stopping capture...", { chunksCount: recordedChunks.length, totalSamples });

  if (scriptProcessorNode) {
    try {
      micState.gainNode.disconnect(scriptProcessorNode);
    } catch (e) {
      console.warn("[RecEngine] gainNode disconnect warning:", e);
    }
    scriptProcessorNode.disconnect();
    scriptProcessorNode = null;
  }

  const samples = new Float32Array(totalSamples);
  let offset = 0;
  for (const chunk of recordedChunks) {
    samples.set(chunk, offset);
    offset += chunk.length;
  }
  recordedChunks = [];
  totalSamples = 0;

  const durationSeconds = samples.length / SAMPLE_RATE;
  console.log("[RecEngine] Capture stopped:", { samplesLength: samples.length, durationSeconds });

  return { samples, durationSeconds };
}

export function createPreviewUrl(wavBlob: Blob): string {
  return URL.createObjectURL(wavBlob);
}

export function revokePreviewUrl(url: string): void {
  URL.revokeObjectURL(url);
}

export function playCountdownBeep(
  audioContext: AudioContext,
  frequency: number = 880,
  duration: number = 0.12
): void {
  const osc = audioContext.createOscillator();
  const env = audioContext.createGain();
  osc.type = "sine";
  osc.frequency.setValueAtTime(frequency, audioContext.currentTime);
  env.gain.setValueAtTime(0.3, audioContext.currentTime);
  env.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + duration);
  osc.connect(env);
  env.connect(audioContext.destination);
  osc.start();
  osc.stop(audioContext.currentTime + duration);
}

export interface QualityMetrics {
  score: number;
  clipping: boolean;
  loudness: number;
  noiseFloor: number;
  timingScore: number;
}

export function analyzeTakeQuality(samples: Float32Array, targetDuration?: number): QualityMetrics {
  if (samples.length === 0) {
    return { score: 0, clipping: false, loudness: 0, noiseFloor: 0, timingScore: 0 };
  }

  // 1. Clipping detection
  let clippingCount = 0;
  for (let i = 0; i < samples.length; i++) {
    if (Math.abs(samples[i]) >= 0.99) {
      clippingCount++;
    }
  }
  const hasClipping = clippingCount > 0;

  // 2. Loudness (RMS)
  let sumSq = 0;
  for (let i = 0; i < samples.length; i++) {
    sumSq += samples[i] * samples[i];
  }
  const rms = Math.sqrt(sumSq / samples.length);
  // Normalize loudness score (ideal RMS around 0.15 - 0.2 for voice)
  const loudnessScore = Math.max(0, 1 - Math.abs(rms - 0.18) * 4);

  // 3. Noise Floor (estimate from quietest 100ms window)
  const windowSize = 4800; // 100ms at 48kHz
  let minWindowRms = Infinity;
  for (let i = 0; i < samples.length - windowSize; i += windowSize) {
    let windowSumSq = 0;
    for (let j = 0; j < windowSize; j++) {
      const s = samples[i + j];
      windowSumSq += s * s;
    }
    const windowRms = Math.sqrt(windowSumSq / windowSize);
    if (windowRms < minWindowRms) minWindowRms = windowRms;
  }
  // Noise floor score: lower is better. -60dB is ~0.001.
  const noiseScore = Math.max(0, 1 - minWindowRms * 50);

  // 4. Timing Score
  let timingScore = 1.0;
  if (targetDuration && targetDuration > 0) {
    const duration = samples.length / 48000;
    const diff = Math.abs(duration - targetDuration);
    timingScore = Math.max(0, 1 - diff / targetDuration);
  }

  // 5. Overall Score (0-100)
  let baseScore = (loudnessScore * 0.4 + noiseScore * 0.3 + timingScore * 0.3) * 100;
  if (hasClipping) baseScore *= 0.7; // Heavy penalty for clipping

  return {
    score: Math.round(Math.max(0, Math.min(100, baseScore))),
    clipping: hasClipping,
    loudness: rms,
    noiseFloor: minWindowRms,
    timingScore
  };
}

const SAMPLE_RATE = 48000;
const FFT_SIZE = 2048;

export type VoiceCaptureMode = "studio" | "original";

export interface MicrophoneState {
  stream: MediaStream;
  audioContext: AudioContext;
  sourceNode: MediaStreamAudioSourceNode;
  gainNode: GainNode;
  analyserNode: AnalyserNode;
  captureMode: VoiceCaptureMode;
  filterNodes: AudioNode[];
}

let currentState: MicrophoneState | null = null;

export async function requestMicrophone(
  mode: VoiceCaptureMode = "original"
): Promise<MicrophoneState> {
  if (currentState && currentState.audioContext.state !== "closed") {
    if (currentState.captureMode === mode) {
      return currentState;
    }
  }

  const isStudio = mode === "studio";
  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        sampleRate: SAMPLE_RATE,
        channelCount: 1,
        echoCancellation: isStudio,
        noiseSuppression: isStudio,
        autoGainControl: isStudio,
      },
    });
  } catch (err) {
    console.error("[Mic] getUserMedia failed for mode", mode, err);
    if (currentState && currentState.audioContext.state !== "closed") {
      console.log("[Mic] Keeping existing mic state as fallback");
      return currentState;
    }
    throw err;
  }

  if (currentState && currentState.audioContext.state !== "closed") {
    await releaseMicrophoneAsync();
  }

  const audioContext = new AudioContext({ sampleRate: SAMPLE_RATE });
  if (audioContext.state === "suspended") {
    await audioContext.resume();
    console.log("[Mic] AudioContext resumed from suspended state");
  }

  const sourceNode = audioContext.createMediaStreamSource(stream);
  const gainNode = audioContext.createGain();
  gainNode.gain.value = 1.0;

  const analyserNode = audioContext.createAnalyser();
  analyserNode.fftSize = FFT_SIZE;
  analyserNode.smoothingTimeConstant = 0.6;
  analyserNode.minDecibels = -90;
  analyserNode.maxDecibels = 0;

  const filterNodes: AudioNode[] = [];

  if (isStudio) {
    const highPassFilter = audioContext.createBiquadFilter();
    highPassFilter.type = "highpass";
    highPassFilter.frequency.value = 80;
    highPassFilter.Q.value = 0.7;
    filterNodes.push(highPassFilter);

    const compressor = audioContext.createDynamicsCompressor();
    compressor.threshold.value = -24;
    compressor.knee.value = 12;
    compressor.ratio.value = 4;
    compressor.attack.value = 0.003;
    compressor.release.value = 0.15;
    filterNodes.push(compressor);

    sourceNode.connect(highPassFilter);
    highPassFilter.connect(compressor);
    compressor.connect(gainNode);
    console.log("[Mic] Studio mode: highpass(80Hz) → compressor → gain");
  } else {
    sourceNode.connect(gainNode);
    console.log("[Mic] Original mode: source → gain (no processing)");
  }

  gainNode.connect(analyserNode);

  currentState = {
    stream,
    audioContext,
    sourceNode,
    gainNode,
    analyserNode,
    captureMode: mode,
    filterNodes,
  };
  return currentState;
}

export function getFrequencyData(state: MicrophoneState): Uint8Array {
  const data = new Uint8Array(state.analyserNode.frequencyBinCount);
  state.analyserNode.getByteFrequencyData(data);
  return data;
}

export function getTimeDomainData(state: MicrophoneState): Uint8Array {
  const data = new Uint8Array(state.analyserNode.fftSize);
  state.analyserNode.getByteTimeDomainData(data);
  return data;
}

export function getAnalyserData(state: MicrophoneState): Uint8Array {
  return getFrequencyData(state);
}

export function setGain(state: MicrophoneState, value: number): void {
  const clamped = Math.max(0, Math.min(2, value));
  state.gainNode.gain.setTargetAtTime(clamped, state.audioContext.currentTime, 0.01);
}

async function releaseMicrophoneAsync(): Promise<void> {
  if (!currentState) return;
  currentState.stream.getTracks().forEach((t) => t.stop());
  if (currentState.audioContext.state !== "closed") {
    await currentState.audioContext.close().catch(() => {});
  }
  currentState = null;
}

export function releaseMicrophone(): void {
  if (!currentState) return;
  currentState.stream.getTracks().forEach((t) => t.stop());
  if (currentState.audioContext.state !== "closed") {
    currentState.audioContext.close().catch(() => {});
  }
  currentState = null;
}

export function getMicState(): MicrophoneState | null {
  return currentState;
}

