export type Theme = "light" | "dark" | "system";

export function getTheme(): Theme {
  return "light";
}

export function applyTheme(theme: Theme) {
  const root = document.documentElement;
  // Check if we are in the Recording Room (Studio Room)
  const isRecordingRoom = window.location.pathname.includes("/room");

  if (isRecordingRoom) {
    root.classList.add("dark");
    root.style.colorScheme = "dark";
    return;
  }

  root.classList.remove("dark");
  root.style.colorScheme = "light";
}

export function initThemeMode() {
  applyTheme("light");

  // Re-apply theme on navigation
  const originalPushState = window.history.pushState;
  window.history.pushState = function(...args) {
    originalPushState.apply(this, args);
    applyTheme("light");
  };

  const originalReplaceState = window.history.replaceState;
  window.history.replaceState = function(...args) {
    originalReplaceState.apply(this, args);
    applyTheme("light");
  };

  window.addEventListener("popstate", () => applyTheme("light"));
}

export function toggleTheme(): Theme {
  // Disabled as per requirements: force light mode globally except Room
  return "light";
}

export type SessionStatus = "scheduled" | "in_progress" | "completed";

export function computeSessionStatus(
  scheduledAt: string | Date,
  durationMinutes: number = 60
): SessionStatus {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  const end = start + durationMinutes * 60 * 1000;
  if (now < start) return "scheduled";
  if (now < end) return "in_progress";
  return "completed";
}

export function isSessionVisibleOnDashboard(
  scheduledAt: string | Date,
  durationMinutes: number = 60
): boolean {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  const windowEnd = start + 3 * 60 * 60 * 1000;
  return now < windowEnd;
}

export function sessionEntryAllowed(
  scheduledAt: string | Date,
  bufferMinutes: number = 5
): boolean {
  const now = Date.now();
  const start = new Date(scheduledAt).getTime();
  return now >= start - bufferMinutes * 60 * 1000;
}

export function formatCountdownTime(scheduledAt: string | Date, bufferMinutes: number = 5): string {
  const target = new Date(scheduledAt).getTime() - bufferMinutes * 60 * 1000;
  const diff = Math.max(0, target - Date.now());
  const hours = Math.floor(diff / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  if (hours > 0) return `${hours}h ${minutes}min`;
  return `${minutes}min`;
}

let initialized = false;

function getMagneticSections(): HTMLElement[] {
  const nodes = Array.from(
    document.querySelectorAll<HTMLElement>(
      'section[id], [data-magnetic-section], main > section, [id="hub-dub"], [id="hubschool"], [id="hub-align"]'
    )
  );
  return nodes.filter((node) => node.offsetHeight > 120);
}

export function initMagneticScroll() {
  if (initialized || typeof window === "undefined") return;
  initialized = true;

  let debounceTimer: number | null = null;
  let autoScrolling = false;
  let releaseTimer: number | null = null;

  const releaseAutoScroll = () => {
    if (releaseTimer) window.clearTimeout(releaseTimer);
    releaseTimer = window.setTimeout(() => {
      autoScrolling = false;
    }, 420);
  };

  const snapToNearest = () => {
    if (autoScrolling) return;
    const sections = getMagneticSections();
    if (!sections.length) return;

    const viewportCenter = window.scrollY + window.innerHeight / 2;
    let nearest = sections[0];
    let nearestDistance = Number.POSITIVE_INFINITY;

    for (const section of sections) {
      const sectionCenter = section.offsetTop + section.offsetHeight / 2;
      const distance = Math.abs(sectionCenter - viewportCenter);
      if (distance < nearestDistance) {
        nearest = section;
        nearestDistance = distance;
      }
    }

    const maxSnapDistance = Math.min(window.innerHeight * 0.6, 520);
    if (nearestDistance > maxSnapDistance) return;

    const target = nearest.offsetTop - (window.innerHeight - nearest.offsetHeight) / 2;
    const clampedTarget = Math.max(0, target);
    const delta = Math.abs(window.scrollY - clampedTarget);
    if (delta < 12) return;

    autoScrolling = true;
    window.scrollTo({ top: clampedTarget, behavior: "smooth" });
    releaseAutoScroll();
  };

  const onScroll = () => {
    if (autoScrolling) return;
    if (debounceTimer) window.clearTimeout(debounceTimer);
    debounceTimer = window.setTimeout(snapToNearest, 140);
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("wheel", releaseAutoScroll, { passive: true });
  window.addEventListener("touchmove", releaseAutoScroll, { passive: true });
}

